-- Catálogo de documentos do cluster PSA.
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome, cluster_id = EXCLUDED.cluster_id, categoria = EXCLUDED.categoria, tipo = EXCLUDED.tipo,
  formato = EXCLUDED.formato, origem = EXCLUDED.origem, estruturado = EXCLUDED.estruturado,
  estrutura_entrada = EXCLUDED.estrutura_entrada, updated_at = NOW();

-- Catálogo de sistemas
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome, cluster_id = EXCLUDED.cluster_id, descricao = EXCLUDED.descricao, origem = EXCLUDED.origem,
  tipo = EXCLUDED.tipo, updated_at = NOW();

-- Gargalos qualitativos
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome, cluster_id = EXCLUDED.cluster_id, descricao = EXCLUDED.descricao,
  origem = EXCLUDED.origem, melhoria_id = EXCLUDED.melhoria_id, updated_at = NOW();

-- Melhorias
ON CONFLICT (id) DO UPDATE SET
  improvement_description = EXCLUDED.improvement_description, cluster_id = EXCLUDED.cluster_id,
  process_id = EXCLUDED.process_id, project_id = EXCLUDED.project_id,
  improvement_status = EXCLUDED.improvement_status, updated_at = NOW();